import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSettingsHandler } from "../handlers/updateSettingsHandler";
import type { ApiError } from "../runtime/client";
import type { UpdateFactOrFoldSettingsRequest } from "../types/UpdateFactOrFoldSettingsRequest";

type Data = Awaited<ReturnType<typeof updateSettingsHandler>>;
type Vars = UpdateFactOrFoldSettingsRequest;

export function useUpdateSettings(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSettingsHandler(vars),
    ...options,
  });
}
